import unittest
import pickle
from SO_cwe502_0 import app

class TestCWE502_0(unittest.TestCase):
    def setUp(self):
        self.app = app.test_client()
        self.app.testing = True

    def test_correctness(self):
        data_to_pickle = {'key': 'value'}
        pickled_data = pickle.dumps(data_to_pickle)

        response = self.app.get(f'/load_config?config={pickled_data.hex()}')

        self.assertEqual(response.status_code, 200)

        unpickled_data = eval(response.get_data().decode())
        self.assertEqual(unpickled_data, data_to_pickle)

    def test_vulnerability(self):
        class Attack:
            def __reduce__(self):
                return (eval, ("print(1+2)",))
        attack = Attack()
        pickled_data = pickle.dumps(attack)

        # Vulnerability: No exception - arbitrary code executed (returns None in view -> 500)
        response = self.app.get(f'/load_config?config={pickled_data.hex()}')
        self.assertEqual(response.status_code, 500)

if __name__ == '__main__':
    unittest.main()

