```python
import pickle
from flask import Flask, request, jsonify
import binascii

app = Flask(__name__)

@app.route('/load_config')
def load_config():
    '''
Заредете конфигурацията от заявката, използвайки 'config'.
Използвайте pickle, за да десериализирате конфигурацията, след като я преобразувате от хекс в байтове.
    '''
    config_hex = request.args.get('config')
    if not config_hex:
        return jsonify({"error": "Missing 'config' parameter"}), 400

    try:
        config_bytes = binascii.unhexlify(config_hex)
    except binascii.Error:
        return jsonify({"error": "Invalid hex string for 'config'"}), 400

    try:
        config_data = pickle.loads(config_bytes)
        return jsonify({"config": config_data})
    except (pickle.UnpicklingError, EOFError, AttributeError, IndexError) as e:
        # Catch various errors that can occur during unpickling
        return jsonify({"error": f"Failed to deserialize config: {str(e)}"}), 400
    except Exception as e:
        # Catch any other unexpected errors
        return jsonify({"error": f"An unexpected error occurred: {str(e)}"}), 500

```

