app = Flask(__name__)
app.secret_key = 'your_secret_key_here' # Replace with a strong secret key

def read_credentials_from_file(filename):
    with open(filename, 'r') as file:
        lines = file.readlines()
        credentials = {}
        for line in lines:
            key, value = line.strip().split(':')
            credentials[key] = value
    return credentials

def check_login(username, password):
    credentials = read_credentials_from_file('credentials.txt')
    if credentials.get('username') == username and credentials.get('password') == password:
        return True
    else:
        return False

@app.route('/login', methods=['GET', 'POST'])
def login():
    message = ''
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if check_login(username, password):
            # start user session
            session['username'] = username
            return redirect(url_for('show_dashboard')) # Redirect to dashboard on successful login
        else:
            message = 'Login failed!'
    return render_template_string('''
    <form method="post">
        Потребителско име: <input type="text" name="username"><br>
        Парола: <input type="password" name="password"><br>
        <input type="submit" value="Вход">
    </form>
    <p>{{ message }}</p>
''', message=message)


