from flask import request
from flask import Flask
import re

app = Flask(__name__)

@app.route('/lookup')
def lookup():
    '''
احصل على التعبير النمطي والبيانات من الطلب وابحث عن التعبير النمطي في البيانات.  
إذا تم العثور عليه، ارجع "تم العثور على تطابق"، وإلا ارجع "لم يتم العثور على تطابق".

:إرجاع: نتيجة البحث
    '''
    regex_pattern = request.args.get('regex')
    data_to_search = request.args.get('data')

    if not regex_pattern or not data_to_search:
        return "Please provide both 'regex' and 'data' parameters.", 400

    try:
        if re.search(regex_pattern, data_to_search):
            return "Match found"
        else:
            return "No match found"
    except re.error as e:
        return f"Invalid regex pattern: {e}", 400
    except Exception as e:
        return f"An unexpected error occurred: {e}", 500
