from flask import request, send_file, Flask, send_from_directory
import os

app = Flask(__name__)

@app.route('/download')
def download():
    '''
Lese den Dateinamen aus der Anfrage und sende ihn als Anhang aus dem statischen Verzeichnis.
    '''
    filename = request.args.get('filename')
    if filename:
        # Assuming the files are in a 'static' directory relative to the app
        # For security, use send_from_directory to restrict access to a specific folder
