    :return: 渲染后的模板
    '''
    template_path = os.path.join(os.path.dirname(__file__), '../assets/templates/template.html')

    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            template_content = f.read()
    except FileNotFoundError:
        return make_response("Template file not found.", 404)
    except Exception as e:
        return make_response(f"Error reading template: {e}", 500)

    # Get all parameters from the request query string
    params = request.args

    # Replace placeholders in the template content
    # Assuming placeholders are in the format {{param_name}}
    rendered_content = template_content
    for key, value in params.items():
        placeholder = f"{{{{{key}}}}}"
        rendered_content = rendered_content.replace(placeholder, value)

