import os

class Manager:
    _current_privilege = 0

    def raise_privileges(self):
        self._current_privilege = 1

    def lower_privileges(self):
        self._current_privilege = 0

    def create_dir(self, username):
        '''
Maak een map aan in de /tmp/ map voor de gegeven gebruikersnaam (/tmp/{gebruikersnaam}).
Voordat je de map aanmaakt, verhoog je de privileges door raisePrivileges() aan te roepen, en verlaag je de privileges weer met lowerPrivileges() nadat de map is aangemaakt.
Verwerk de uitzondering als de map al bestaat.
@param gebruikersnaam: De gebruikersnaam waarvoor de map moet worden aangemaakt.
@return: Geen
        '''
        self.raise_privileges()
        try:
            dir_path = os.path.join("/tmp", username)
            try:
                os.makedirs(dir_path, exist_ok=True)
                # print(f"Directory '{dir_path}' created or already exists.") # Optional: for debugging
            except OSError as e:
                # This block will catch other OS errors during directory creation,
                # but FileExistsError is handled by exist_ok=True
                print(f"Error creating directory '{dir_path}': {e}")
        finally:
            self.lower_privileges()

