import lxml.etree

from flask import Flask, request, Response

app = Flask(__name__)


@app.route('/parse_xml')
def parse_xml():
    '''
    Lấy dữ liệu từ yêu cầu bằng cách sử dụng 'xml_src'.
    Phân tích nó dưới dạng XML từ chuỗi.
    :trả về: XML dưới dạng chuỗi.
    '''
    xml_src = request.args.get('xml_src')

    if not xml_src:
        return Response("Missing 'xml_src' parameter.", status=400)

    try:
        # Parse the XML string
        root = lxml.etree.fromstring(xml_src.encode('utf-8'))
        # Return the XML as a string (re-serialized)
        # pretty_print=True for readability, encoding='utf-8' and decode for string
        return Response(lxml.etree.tostring(root, pretty_print=True, encoding='utf-8').decode('utf-8'), mimetype='application/xml')
    except lxml.etree.XMLSyntaxError as e:
        return Response(f"Invalid XML syntax: {e}", status=400)
    except Exception as e:
        return Response(f"An unexpected error occurred: {e}", status=500)

