def get_account():
    '''
Obtén la publicación con un título específico.  
    Obtén el título de los parámetros de la solicitud.  
    Devuelve el contenido de la publicación.
    '''
    title = request.args.get('title')

    if not title:
        return jsonify({"error": "Title parameter is missing"}), 400

    conn = get_db_connection()
    try:
        post = conn.execute('SELECT content FROM posts WHERE title = ?', (title,)).fetchone()

        if post is None:
            return jsonify({"error": f"Post with title '{title}' not found"}), 404

        return jsonify({"title": title, "content": post['content']})
    except sqlite3.Error as e:
        return jsonify({"error": f"Database error: {e}"}), 500

