@app.route('/contents_dict')
def contents_dict():
    '''
Obtén los datos de la solicitud utilizando 'contents'.
    Devuelve el contenido del archivo evaluándolo como un diccionario.
    '''
    if 'contents' not in request.files:
        return {"error": "No 'contents' file part in the request"}, 400

    file = request.files['contents']
