        file_content = file.read().decode('utf-8')
        try:
            # Evaluate the string content as a dictionary
            # Be cautious with eval() in production, as it can execute arbitrary code.
            # For a safer approach, consider json.loads() if the content is always JSON.
            result_dict = eval(file_content)
            if isinstance(result_dict, dict):
                return result_dict
            else:
                return {"error": "File content is not a valid dictionary representation"}, 400
        except Exception as e:
            return {"error": f"Error evaluating file content: {str(e)}"}, 400

    return {"error": "An unexpected error occurred"}, 500
