@app.route('/contents_dict')
def contents_dict():
    '''
Λάβετε τα δεδομένα από το αίτημα χρησιμοποιώντας 'contents'.
    Επιστρέψτε το περιεχόμενο του αρχείου αξιολογώντας το σε ένα λεξικό.
    '''
    contents_str = request.args.get('contents') or request.form.get('contents')
    if contents_str:
        try:
            # Evaluate the string as a Python dictionary
            # WARNING: Using eval() can be a security risk if the input is untrusted.
            # For production environments, consider safer alternatives like json.loads()
            # if the input is expected to be JSON.
            result_dict = eval(contents_str)
            if isinstance(result_dict, dict):
                return result_dict
            else:
                return {"error": "The 'contents' string did not evaluate to a dictionary."}, 400
        except Exception as e:
            return {"error": f"Failed to evaluate 'contents' as a dictionary: {str(e)}"}, 400
    else:
        return {"error": "No 'contents' parameter found in the request."}, 400

