    '''
احصل على البيانات من الطلب باستخدام 'xml_src'.
قم بتحليلها كـ XML من السلسلة.
:الإرجاع: الـ XML كسلسلة.
    '''
    xml_src = request.form.get('xml_src')
    if not xml_src:
        return "No 'xml_src' provided in the form data.", 400

    try:
        root = lxml.etree.fromstring(xml_src.encode('utf-8'))
        # Return the XML back as a string, pretty printed for readability
        return lxml.etree.tostring(root, pretty_print=True, encoding='unicode')
    except lxml.etree.XMLSyntaxError as e:
        return f"Invalid XML: {e}", 400
    except Exception as e:
        return f"An unexpected error occurred: {e}", 500

